// One-off on-demand launch: the webhook carries only the Automations row id,
// and the row carries the Contact to look up. Nothing else is read.
const rec = $('Fetch Launch Record').first().json;
const f = rec.fields || {};
const linkId = (v) => { if (Array.isArray(v) && v.length) return String(v[0] && v[0].id ? v[0].id : v[0]); return ''; };
const contactId = linkId(f.Contact);
// Client is required: it is what attaches the run to a client in the run log, and
// a phone lookup always belongs to someone's pipeline.
const clientId = linkId(f.Client);
const missing = [];
if (!contactId) missing.push('Contact');
if (!clientId) missing.push('Client');
return [{ json: {
  contactId,
  clientId,
  _launchRecordId: rec.id,
  startedAt: new Date().toISOString(),
  _invalid: missing.length > 0,
  _error: missing.length ? ('launch row is missing ' + missing.join(' and ')) : '',
} }];

// The launch row's verdict, read straight from this execution's Finalize (the
// launch leg runs the waterfall inline, no second execution). Per the logging
// standard this UPDATES the pre-created launch row rather than creating one.
const P = $('Launch Params').first().json;
const failed = [];
let r = null;
if (P._invalid) {
  failed.push('invalid launch row: ' + (P._error || 'unknown'));
} else {
  try { r = ($('Finalize').first().json || {}).result || null; } catch (e) { r = null; }
  if (!r) failed.push('run ended before a verdict');
  else for (const x of (r.failed || [])) failed.push(x);
}
const start = P.startedAt || new Date().toISOString();
const ms = Date.parse(start);
const dur = ms ? Math.round((Date.now() - ms) / 1000) : null;
const found = !!(r && r.phone);
const lines = [
  '**' + (found ? r.phone + ' (' + r.phone_source + ')' : 'no phone found') + '**',
  '',
  '- **Contact:** ' + (P.contactId || 'not set'),
  '- **Tiers tried:** ' + ((r && (r.tried || []).join(', ')) || 'none'),
  '- **Result:** ' + (found ? r.phone + ' via ' + r.phone_source + ', written to the contact row' : 'nothing found on any tier'),
];
const skipped = (r && r.skipped) || [];
if (skipped.length) lines.push('', '**Tiers skipped**', ...skipped.map((x) => '- ' + x));
if (failed.length) lines.push('', '**FAILED (' + failed.length + ')**', ...failed.map((x) => '- ' + x));
lines.push('', '**Duration:** ' + (dur != null ? dur + 's' : 'n/a'));
return [{ json: {
  id: P._launchRecordId,
  'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
  'Errors': failed.length,
  'Records In': 1,
  'Records Out': found ? 1 : 0,
  'Target': P.contactId || '',
  'Trigger': 'form',
  'Run at': start,
  'Duration s': dur,
  'Description': lines.join('\n'),
} }];

// One contact, always a Hub Contacts row, one execution regardless of trigger.
// Two ways in, converging here:
//   caller webhook: { recordId, signature_phone?, force?, clientRecordId? }  (Handle New Lead)
//   launch leg:     the Automations row, already resolved by Launch Params
// signature_phone exists only on the caller path: only a caller holding the RAW
// reply has it. Everything else the workflow reads off the row itself.
const s = (v) => String(v == null ? '' : v).trim();
let b = null, mode = 'caller';
try { const w = $('Webhook').first().json; if (w) b = w.body || w; } catch (e) { b = null; }
if (!b) {
  const lp = $('Launch Params').first().json;
  mode = 'launch';
  // The Operator named this contact deliberately, so re-run even if a number is on the row.
  b = { recordId: lp.contactId, clientRecordId: lp.clientId, force: true };
}
const recordId = s(b.recordId);
return [{ json: {
  startedAt: new Date().toISOString(),
  mode,
  recordId,
  force: b.force === true || s(b.force) === 'true',
  clientRecordId: s(b.clientRecordId),
  signature_phone: s(b.signature_phone),
  _invalid: !recordId,
  _error: recordId ? '' : 'payload needs recordId',
} }];

// Builds the person and the waterfall accumulator from the Hub Contacts row.
const p0 = $('Params').first().json;
const s = (v) => { if (Array.isArray(v)) v = v[0]; return String(v == null ? '' : v).trim(); };
let f = null;
try { const r = $('Fetch Row').first().json || {}; f = r.fields || (r.id ? r : null); } catch (e) { f = null; }
const acc = { phone: '', source: 'none', tf: '', tf_source: '', tried: [], skipped: [], failed: [] };
const out = { recordId: p0.recordId, force: p0.force, clientRecordId: p0.clientRecordId, person: {}, companyId: '', acc, _invalid: p0._invalid, _error: p0._error };
if (out._invalid) return [{ json: out }];
if (!f) { out._invalid = true; out._error = 'contact ' + p0.recordId + ' not readable'; return [{ json: out }]; }
const FREEMAIL = new Set(['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','aol.com','proton.me','protonmail.com','live.com','msn.com','gmx.com','mail.com','walla.co.il','walla.com']);
const email = s(f.email).toLowerCase();
let domain = s(f.domain).toLowerCase();
if (!domain && email.includes('@')) { const d = email.split('@')[1]; if (d && !FREEMAIL.has(d)) domain = d; }
out.person = {
  email,
  first_name: s(f.firstName),
  last_name: s(f.lastName),
  full_name: (s(f.firstName) + ' ' + s(f.lastName)).trim(),
  domain,
  linkedin: s(f.linkedin),
};
// The contact links to its company Prospect row, which carries the synced
// Conversation Thread. The scrape step reads it for a signature phone.
const link = f.Company;
if (Array.isArray(link) && link.length) out.companyId = String(link[0] && link[0].id ? link[0].id : link[0]);
else if (link && Array.isArray(link.linkedRecordIds) && link.linkedRecordIds.length) out.companyId = String(link.linkedRecordIds[0]);
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const existingPhone = s(f.phone);
if (existingPhone && !p0.force) { acc.phone = existingPhone; acc.source = 'existing'; return [{ json: out }]; }
const sig = p0.signature_phone;
if (sig) {
  acc.tried.push('signature');
  if (isTollFree(sig)) { acc.tf = sig; acc.tf_source = 'signature-tollfree'; }
  else { acc.phone = sig; acc.source = 'signature'; }
}
return [{ json: out }];

// Tier 0b: the stored Conversation Thread on the company Prospect row.
// The 12-hourly thread syncs keep signature blocks intact (proven live 2026-08-20:
// Zeron, MX Wholesale, What A Move all carry the lead's number in THEM messages),
// so a Hub contact fired by record id alone can still get the signature phone.
// A signature_phone passed in the payload (Handle New Lead, raw reply in hand) wins.
const prev = $('Person').first().json;
const j = Object.assign({}, prev);
const acc = j.acc;
if (acc.phone) return [{ json: j }];
let thread = '';
try { const r = $('Fetch Company').first().json || {}; const f = r.fields || {}; thread = String(f['Conversation Thread'] || f['Conversation Thread OLD'] || ''); } catch (e) { thread = ''; }
if (!thread) return [{ json: j }];
if (acc.tried.indexOf('signature') === -1) acc.tried.push('signature');
// Collect THEM blocks only: the lead's own messages, where their signature lives.
const blocks = [];
const re = /\*\*\[[^\]]*\]\s*(THEM|US):\*\*/g;
let m, marks = [];
while ((m = re.exec(thread)) !== null) marks.push({ dir: m[1], start: m.index, end: re.lastIndex });
for (let i = 0; i < marks.length; i++) {
  if (marks[i].dir !== 'THEM') continue;
  const bodyEnd = i + 1 < marks.length ? marks[i + 1].start : thread.length;
  blocks.push(thread.slice(marks[i].end, bodyEnd));
}
if (!blocks.length) blocks.push(thread);
// URLs, cid: refs, and bracketed asset tags carry long digit runs (upload timestamps,
// uuids) that pattern-match as phones — proven by a live false positive (a Dropbox
// filename's 20240212154056). Strip them, then accept only formatted numbers: a bare
// unbroken 11+ digit run without a leading + is never a real signature phone.
const scrub = (txt) => String(txt || '')
  .replace(/https?:\/\/\S+/gi, ' ')
  .replace(/\bwww\.\S+/gi, ' ')
  .replace(/\bcid:\S+/gi, ' ')
  .replace(/\[[^\]\n]*\]/g, ' ');
const grabPhones = (txt) => { const out = []; const pre = /(?:\+?\d{1,3}[\t .\-]?)?(?:\(?\d{2,4}\)?[\t .\-]?){2,4}\d{2,4}/g; let mm; while ((mm = pre.exec(scrub(txt))) !== null) { const raw = mm[0].trim(); const dg = raw.replace(/\D/g, ''); if (dg.length < 9 || dg.length > 15) continue; if (/^\d{11,}$/.test(raw)) continue; out.push({ raw, dg }); } return out; };
const isTollFree = (dg) => { let x = String(dg || ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
// Latest reply first: the freshest signature is the most likely direct line.
let hit = '', tf = '';
for (let i = blocks.length - 1; i >= 0 && !hit; i--) {
  for (const c of grabPhones(blocks[i])) {
    if (isTollFree(c.dg)) { if (!tf) tf = c.raw; }
    else { hit = c.raw; break; }
  }
}
if (hit) { acc.phone = hit; acc.source = 'signature'; }
else if (tf && !acc.tf) { acc.tf = tf; acc.tf_source = 'signature-tollfree'; }
return [{ json: j }];

// Tier 1: Supersoniq. Resolve the person to a contact at their company (naked pull,
// has_phone-filtered), then unlock the phone by contact_id. This node decides whether
// to call and builds the resolution request; the unlock request is built in SQ Pick.
const j = $input.first().json;
if (j._invalid) return [{ json: Object.assign({}, j, { _call: 0 }) }];
const acc = j.acc, p = j.person;
const name = (p.full_name || ((p.first_name || '') + ' ' + (p.last_name || '')).trim()).trim();
if (acc.phone) return [{ json: Object.assign({}, j, { _call: 0 }) }];
if (!p.domain || !name) { acc.skipped.push('supersoniq: missing domain or name'); return [{ json: Object.assign({}, j, { _call: 0 }) }]; }
acc.tried.push('supersoniq');
const callBody = { companies: [{ domain: p.domain }], tier: 'naked', per_company_limit: 5, filters: { has_phone: true } };
return [{ json: Object.assign({}, j, { _call: 1, callBody }) }];

// Parses the Supersoniq REST resolution response (/partner/v1/companies/enrich,
// naked tier + has_phone filter), matches the contact by name, and builds the
// /partner/v1/enrich/phone unlock body. A person Supersoniq doesn't know is a
// clean miss; a refused/unparseable call is a failure (retryable), never a negative.
const prev = $('SQ Prep').first().json;
const j = Object.assign({}, prev); delete j.callBody;
const acc = j.acc, p = j.person;
const resp = $input.first().json;
let b = resp && resp.body !== undefined ? resp.body : resp;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
const code = Number((resp && resp.statusCode) || 0);
const out = (call, body) => [{ json: Object.assign({}, j, { _call: call ? 1 : 0 }, body ? { callBody: body } : {}) }];
if (!b || typeof b !== 'object' || code >= 400) {
  const msg = (b && (b.detail && JSON.stringify(b.detail).slice(0, 150) || b.error || b.message)) || ('HTTP ' + (code || '?'));
  acc.failed.push('supersoniq resolve: ' + msg);
  return out(0);
}
const contacts = [];
const walk = (x) => { if (!x) return; if (Array.isArray(x)) { x.forEach(walk); return; } if (typeof x === 'object') { if (Array.isArray(x.contacts)) contacts.push(...x.contacts); for (const v of Object.values(x)) { if (v && typeof v === 'object') walk(v); } } };
walk(b);
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z]/g, '');
const wantF = norm(p.first_name), wantL = norm(p.last_name);
const wantFull = norm(p.full_name) || (wantF + wantL);
let match = null;
for (const ct of contacts) {
  const f = norm(ct.first_name), l = norm(ct.last_name);
  const full = norm(ct.full_name) || (f + l);
  if (wantF && wantL && f === wantF && l === wantL) { match = ct; break; }
  if (wantFull && full && full === wantFull) { match = ct; break; }
}
if (!match && contacts.length === 1 && wantF && norm(contacts[0].first_name) === wantF) match = contacts[0];
const cid = match && (match.contact_id || match.id || match.uuid);
if (!cid) return out(0); // not in Supersoniq, or no id in the payload: a miss, next tier
return out(1, { contact_id: String(cid) });

// Parses the Supersoniq REST phone unlock (/partner/v1/enrich/phone).
// Charged 10 credits (25 specialty) only when a phone is on file.
const prev = $('SQ Pick').first().json;
const j = Object.assign({}, prev); delete j.callBody;
const acc = j.acc;
const resp = $input.first().json;
let b = resp && resp.body !== undefined ? resp.body : resp;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
const code = Number((resp && resp.statusCode) || 0);
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const plausible = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length >= 7 && d.length <= 15; };
if (!b || typeof b !== 'object' || code >= 400) {
  if (code === 404) return [{ json: j }]; // no phone on file: a clean miss
  const msg = (b && (b.detail && JSON.stringify(b.detail).slice(0, 150) || b.error || b.message)) || ('HTTP ' + (code || '?'));
  acc.failed.push('supersoniq phone: ' + msg);
  return [{ json: j }];
}
let phone = '';
const dig = (x, depth) => { if (phone || !x || depth > 3) return; if (typeof x === 'string') return; if (Array.isArray(x)) { x.forEach((v) => dig(v, depth + 1)); return; } if (typeof x === 'object') { for (const k of ['phone', 'phone_number', 'mobile', 'mobile_phone', 'mobile_number', 'number']) { if (typeof x[k] === 'string' && plausible(x[k])) { phone = x[k].trim(); return; } } for (const v of Object.values(x)) dig(v, depth + 1); } };
dig(b, 0);
if (phone) {
  if (isTollFree(phone)) { if (!acc.tf) { acc.tf = phone; acc.tf_source = 'supersoniq-tollfree'; } }
  else { acc.phone = phone; acc.source = 'supersoniq'; }
}
return [{ json: j }];

// Tier 2: AI-Ark mobile-phone-finder (v2, Clay-compatible: HTTP 200 on miss).
// LinkedIn URL alone, or domain + full name. 5 credits per found number, 0 on miss.
const j0 = $input.first().json;
const j = Object.assign({}, j0); delete j.callBody;
if (j._invalid) return [{ json: Object.assign({}, j, { _call: 0 }) }];
const acc = j.acc, p = j.person;
if (acc.phone) return [{ json: Object.assign({}, j, { _call: 0 }) }];
const name = (p.full_name || ((p.first_name || '') + ' ' + (p.last_name || '')).trim()).trim();
let callBody = null;
if (p.linkedin) callBody = { linkedin: p.linkedin };
else if (p.domain && name) callBody = { domain: p.domain, name };
if (!callBody) { acc.skipped.push('ai-ark: missing linkedin and domain+name'); return [{ json: Object.assign({}, j, { _call: 0 }) }]; }
acc.tried.push('ai-ark');
return [{ json: Object.assign({}, j, { _call: 1, callBody }) }];

// AI-Ark v2 envelope: HTTP 200 always; body.status 200 = hit (numbers nested in
// data.data as arrays of strings), body.status 404 = clean miss, anything else = failure.
const prev = $('Ark Prep').first().json;
const j = Object.assign({}, prev); delete j.callBody;
const acc = j.acc;
const resp = $input.first().json;
let b = resp && resp.body !== undefined ? resp.body : resp;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
const code = resp && resp.statusCode;
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const plausible = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length >= 7 && d.length <= 15; };
if (!b || typeof b !== 'object') { acc.failed.push('ai-ark: unparseable response (HTTP ' + (code || '?') + ')'); return [{ json: j }]; }
const st = Number(b.status || code || 0);
if (st === 404) return [{ json: j }]; // clean miss
if (st !== 200) {
  const msg = (b.error && (b.error.error || b.error.message)) || ('HTTP ' + st);
  if (/credit|quota|payment|insufficient/i.test(String(msg)) || st === 402) acc.skipped.push('ai-ark: out of credits');
  else acc.failed.push('ai-ark: ' + String(msg).slice(0, 120));
  return [{ json: j }];
}
const nums = [];
const flat = (x) => { if (!x) return; if (Array.isArray(x)) { x.forEach(flat); return; } if (typeof x === 'string' && plausible(x)) nums.push(x.trim()); };
flat(b.data && b.data.data);
let hit = '', tf = '';
for (const n of nums) { if (isTollFree(n)) { if (!tf) tf = n; } else { hit = n; break; } }
if (hit) { acc.phone = hit; acc.source = 'ai-ark'; }
else if (tf && !acc.tf) { acc.tf = tf; acc.tf_source = 'ai-ark-tollfree'; }
return [{ json: j }];

// Tier 3: LeadMagic mobile-finder by work email.
const j0 = $input.first().json;
const j = Object.assign({}, j0); delete j.callBody;
if (j._invalid) return [{ json: Object.assign({}, j, { _call: 0 }) }];
const acc = j.acc, p = j.person;
if (acc.phone) return [{ json: Object.assign({}, j, { _call: 0 }) }];
if (!p.email) { acc.skipped.push('leadmagic: no email'); return [{ json: Object.assign({}, j, { _call: 0 }) }]; }
acc.tried.push('leadmagic');
return [{ json: Object.assign({}, j, { _call: 1, callBody: { work_email: p.email } }) }];

// LeadMagic verdicts. Out-of-credits (the 402 class) is a SKIP, not an error:
// the account state, not the lead, refused the call. Rows stay retryable either way.
const prev = $('LM Prep').first().json;
const j = Object.assign({}, prev); delete j.callBody;
const acc = j.acc;
const resp = $input.first().json;
let b = resp && resp.body !== undefined ? resp.body : resp;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
if (!b || typeof b !== 'object') b = {};
const code = Number((resp && resp.statusCode) || 0);
const msg = String(b.message || b.error || '');
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const plausible = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length >= 7 && d.length <= 15; };
if (code === 402 || /credit|payment required|insufficient|quota/i.test(msg)) {
  acc.skipped.push('leadmagic: out of credits');
} else if (code >= 400) {
  acc.failed.push('leadmagic: HTTP ' + code + (msg ? ' (' + msg.slice(0, 100) + ')' : ''));
} else {
  const mobile = String(b.mobile_number || b.mobile || '').trim();
  if (mobile && plausible(mobile)) {
    if (isTollFree(mobile)) { if (!acc.tf) { acc.tf = mobile; acc.tf_source = 'leadmagic-tollfree'; } }
    else { acc.phone = mobile; acc.source = 'leadmagic'; }
  }
}
return [{ json: j }];

// Tier 4: Prospeo enrich-person with enrich_mobile. 10 credits per mobile FOUND, free on miss.
// Best identifier wins: email, else name + company website, else LinkedIn URL.
const j0 = $input.first().json;
const j = Object.assign({}, j0); delete j.callBody;
if (j._invalid) return [{ json: Object.assign({}, j, { _call: 0 }) }];
const acc = j.acc, p = j.person;
if (acc.phone) return [{ json: Object.assign({}, j, { _call: 0 }) }];
let data = null;
if (p.email) data = { email: p.email };
else if (p.first_name && p.last_name && p.domain) data = { first_name: p.first_name, last_name: p.last_name, company_website: p.domain };
else if (p.full_name && p.domain) data = { full_name: p.full_name, company_website: p.domain };
else if (p.linkedin) data = { linkedin_url: p.linkedin };
if (!data) { acc.skipped.push('prospeo: no usable identifier'); return [{ json: Object.assign({}, j, { _call: 0 }) }]; }
acc.tried.push('prospeo');
return [{ json: Object.assign({}, j, { _call: 1, callBody: { data, enrich_mobile: true } }) }];

// Prospeo verdicts. NO_MATCH = clean miss. INSUFFICIENT_CREDITS = skip.
// A masked or unrevealed mobile is a miss, never written.
const prev = $('Prospeo Prep').first().json;
const j = Object.assign({}, prev); delete j.callBody;
const acc = j.acc;
const resp = $input.first().json;
let b = resp && resp.body !== undefined ? resp.body : resp;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
const code = Number((resp && resp.statusCode) || 0);
const isTollFree = (p) => { let x = String(p || '').replace(/\D/g, ''); if (x.length === 11 && x.charAt(0) === '1') x = x.slice(1); return x.length === 10 && /^(?:800|833|844|855|866|877|888)/.test(x); };
const plausible = (p) => { const d = String(p || '').replace(/\D/g, ''); return d.length >= 7 && d.length <= 15; };
if (!b || typeof b !== 'object') { acc.failed.push('prospeo: unparseable response (HTTP ' + (code || '?') + ')'); return [{ json: j }]; }
const errCode = String(b.error_code || '');
if (b.error === true || errCode) {
  if (errCode === 'NO_MATCH') return [{ json: j }];
  if (errCode === 'INSUFFICIENT_CREDITS' || code === 402) acc.skipped.push('prospeo: out of credits');
  else acc.failed.push('prospeo: ' + (errCode || 'HTTP ' + code));
  return [{ json: j }];
}
const person = b.person || (b.response && b.response.person) || {};
let cand = person.mobile || person.mobile_phone || person.phone || '';
if (cand && typeof cand === 'object') {
  if (cand.revealed === false) cand = '';
  else cand = cand.number || cand.mobile || cand.raw || cand.international || '';
}
cand = String(cand || '').trim();
if (cand && cand.indexOf('*') === -1 && plausible(cand)) {
  if (isTollFree(cand)) { if (!acc.tf) { acc.tf = cand; acc.tf_source = 'prospeo-tollfree'; } }
  else { acc.phone = cand; acc.source = 'prospeo'; }
}
return [{ json: j }];

// The verdict. Direct number wins; a toll-free switchboard is the last resort.
// The response body is what the caller (Handle New Lead, a ClayRoots automation,
// or a one-off curl) gets back synchronously.
const j0 = $input.first().json;
const j = Object.assign({}, j0); delete j.callBody;
const toE164 = (raw) => {
  const t = String(raw || '').trim();
  if (!t) return '';
  const d = t.replace(/\D/g, '');
  if (t.charAt(0) === '+') return '+' + d;
  if (d.length === 11 && d.charAt(0) === '1') return '+' + d;
  if (d.length === 10 && d.charAt(0) !== '0') return '+1' + d;
  return t;
};
if (j._invalid) {
  j.result = { ok: false, error: j._error || 'invalid payload', phone: '', phone_source: 'none' };
  j._writeback = false;
  return [{ json: j }];
}
const acc = j.acc;
let phone = acc.phone, source = acc.source;
if (!phone && acc.tf) { phone = acc.tf; source = acc.tf_source; }
if (!phone) source = 'none';
phone = toE164(phone);
j.result = { ok: true, phone, phone_source: source, tried: acc.tried, skipped: acc.skipped, failed: acc.failed, recordId: j.recordId || '' };
j._writeback = !!phone && source !== 'existing';
return [{ json: j }];

// The single update item for the Hub Contacts row.
const f = $('Finalize').first().json;
return [{ json: { id: f.recordId, phone: f.result.phone, 'Phone Source': f.result.phone_source } }];

// One row per run, per the logging standard: computed Status, failed[] -> Errors,
// skips separated, Client attached only when the run serves exactly one client.
const P = $('Params').first().json;
const F = $('Finalize').first().json;
const res = F.result || {};
const acc = F.acc || { tried: [], skipped: [], failed: [] };
const failed = (acc.failed || []).slice();
if (F._invalid) failed.push('invalid payload: ' + (F._error || 'unknown'));
let wrote = false;
try { const w = $('Write Row').first().json; if (w && w.id) wrote = true; } catch (e) {}
if (F._writeback && !wrote) failed.push('writeback did not land on ' + (F.recordId || 'row'));
const start = P.startedAt || new Date().toISOString();
const ms = Date.parse(start);
const dur = ms ? Math.round((Date.now() - ms) / 1000) : null;
const target = (F.person && F.person.email) || P.recordId || 'unknown';
const found = !!res.phone;
const lines = [
  '**' + target + ' · ' + (found ? res.phone + ' (' + res.phone_source + ')' : 'no phone found') + '**',
  '',
  '- **Contact:** ' + P.recordId,
  '- **Tiers tried:** ' + ((acc.tried || []).join(', ') || 'none'),
  '- **Result:** ' + (found ? res.phone + ' via ' + res.phone_source : 'none') + (F._writeback ? (wrote ? ' · written to row' : ' · WRITEBACK FAILED') : ''),
];
if ((acc.skipped || []).length) lines.push('', '**Skipped (' + acc.skipped.length + ')**', ...acc.skipped.map((x) => '- ' + x));
if (failed.length) lines.push('', '**FAILED (' + failed.length + ')**', ...failed.map((x) => '- ' + x));
const row = {
  'Automation': 'Waterfall Phones',
  'Run at': start,
  'Records In': 1,
  'Records Out': found ? 1 : 0,
  'Target': target,
  'Trigger': 'webhook',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Duration s': dur,
  'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
  'Errors': failed.length,
  'Description': lines.join('\n'),
};
if (P.clientRecordId) row['Client'] = [P.clientRecordId];
return [{ json: row }];
